let realJob=null,realPoll=null,selectedRealId=null;
const realResult=j=>`<section class="panel result-panel"><span class="badge">真实算法计算 · ${j.source==='synthetic'?'合成台阶点云验证':'本地点云'}</span><h2>边坡线提取与自动补线 · 实际成果</h2><div class="facts">${[[j.result.line_counts.crest,'本次坡顶线'],[j.result.line_counts.toe,'本次坡脚线'],[j.result.line_counts.auto_gap,'本次自动补线'],[j.result.total_length_m+' m','本次总长度']].map(([v,n])=>`<div class="fact"><small>${n}</small><strong>${v}</strong></div>`).join('')}</div><p>实际运行耗时：${j.elapsed_s} 秒 · 网格分辨率：${j.result.params.grid_res_m} m</p><div class="toolbar">${j.files.filter(n=>n!=='preview.png').map(n=>`<a class="download-link" href="/api/jobs/${j.id}/files/${n}" download="${n}">${n==='slope_lines_ENU.json'?'全部边坡线 GeoJSON':n==='slope_lines_auto_gap_only_ENU.json'?'自动补线 GeoJSON':n==='slope_lines_base_ENU.json'?'基础边坡线 GeoJSON':n==='run_params.json'?'运行参数与统计':n==='algorithm.log'?'完整日志':n}</a>`).join('')}<button id="realReport">生成真实结果报告</button></div><p class="note">${j.source==='synthetic'?'输入为程序生成的合成台阶点云，仅用于验证真实算法流程，不代表矿区实测效果或精度。':'成果由用户本地点云计算；未进行独立精度验收。'} 输出使用 ENU 局部坐标，单位为米。自动补线数为0时表示当前数据没有通过约束的补线候选。</p></section>`;
function realPanel(){return `<section class="panel result-panel" id="realPanel"><div class="panel-head"><h2>真实算法 · 边坡线提取与自动补线</h2><span class="badge" id="backendStatus">检查本地服务…</span></div><div class="real-config"><div><label for="realSource">点云来源</label><select id="realSource"><option value="synthetic">合成台阶点云（运行验证）</option><option value="local">本机矿区点云</option></select><label for="realPath">本地点云文件路径</label><input id="realPath" placeholder="D:\\数据\\矿区点云.ply 或 .las / .zip" disabled><p class="note">支持二进制 PLY、LAS 0–3 点格式以及包含它们的 ZIP。此路径由本机算法读取，文件不会上传。当前工具不支持 ASCII PLY、LAZ、PCD。</p></div><div class="real-params">${[['grid_res_m','网格分辨率 (m)',1,.25,10],['platform_slope_deg','平台坡度阈值 (°)',10,1,45],['min_line_m','最小线长 (m)',25,1,500],['link_gap_m','线段续接距离 (m)',45,0,150],['auto_gap_max_m','自动补线最大间隙 (m)',120,10,200]].map(([id,n,v,min,max])=>`<label for="${id}">${n}<input id="${id}" type="number" value="${v}" min="${min}" max="${max}" step="${id==='grid_res_m'?'.25':'1'}"></label>`).join('')}<label><input id="realAutoGap" type="checkbox" checked> 自动补线</label><label><input id="realEnhanced" type="checkbox" checked> 增强续接</label></div></div><div class="toolbar"><button class="primary" id="runReal">运行真实算法</button><button id="cancelReal" disabled>取消任务</button><span id="realStage" class="subtle">就绪</span></div><div class="progress"><div id="realProgress" style="width:0%"></div></div><details><summary>运行日志</summary><pre id="realLogs">尚无运行记录</pre></details><div id="realResults"></div></section>`}
function showRealJob(j){realJob=j;selectedRealId=j.id;if(!$('#realPanel'))return;$('#realStage').textContent=j.stage+(j.error?' · '+j.error:'');$('#realProgress').style.width=j.progress+'%';$('#realLogs').textContent=j.logs.join('\n');let busy=['queued','running'].includes(j.status);$('#runReal').disabled=busy;$('#cancelReal').disabled=!busy;if(busy){$('#realResults').innerHTML='<section class="panel result-panel">本次任务正在真实计算，完成后显示结果。</section>';$('#viewLabel').textContent='上次成果预览 · 当前任务计算中'}else if(j.status!=='succeeded'){$('#realResults').innerHTML=''}if(j.status==='succeeded'){$('#realResults').innerHTML=realResult(j);$('#sceneImage').src=`/api/jobs/${j.id}/files/preview.png`;$('#viewLabel').textContent='本次真实计算结果 · '+(j.source==='synthetic'?'合成点云':'本地点云');$('#realReport').onclick=()=>realReport(j)} }
async function realFetch(path,options){let r=await fetch(path,options);let d=await r.json();if(!r.ok)throw Error(d.error||'请求失败');return d}
function watchReal(id){clearInterval(realPoll);let reading=false;realPoll=setInterval(async()=>{if(reading)return;reading=true;try{let j=await realFetch('/api/jobs/'+id);showRealJob(j);if(!['queued','running'].includes(j.status)){clearInterval(realPoll);realPoll=null;toast(j.status==='succeeded'?'真实算法计算完成':j.error||'任务已取消')}}catch(e){clearInterval(realPoll);realPoll=null;toast('本地服务连接中断，请重新启动服务')}finally{reading=false}},1000)}
async function mountReal(){if(!$('#realPanel'))return;$('#realSource').onchange=e=>$('#realPath').disabled=e.target.value!=='local';$('#runReal').onclick=async()=>{let params={};for(let id of ['grid_res_m','platform_slope_deg','min_line_m','link_gap_m','auto_gap_max_m'])params[id]=Number($('#'+id).value);params.auto_gap_enabled=$('#realAutoGap').checked;params.enhanced_link=$('#realEnhanced').checked;$('#runReal').disabled=true;try{let j=await realFetch('/api/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source:$('#realSource').value,path:$('#realPath').value,params})});showRealJob(j);watchReal(j.id)}catch(e){$('#runReal').disabled=false;toast(e.message)}};$('#cancelReal').onclick=async()=>{try{let j=await realFetch('/api/jobs/'+realJob.id+'/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});showRealJob(j)}catch(e){toast(e.message)}};try{await realFetch('/api/health');if(!$('#backendStatus'))return;$('#backendStatus').textContent='已连接 · 本机算法服务';let data=await realFetch('/api/jobs');let last=data.jobs.find(j=>j.id===selectedRealId)||data.jobs[0];if(last){showRealJob(last);if(['queued','running'].includes(last.status))watchReal(last.id)}}catch(e){if($('#backendStatus')){$('#backendStatus').textContent='未连接 · 请使用启动演示';$('#runReal').disabled=true}}}
function realReport(j){let counts=j.result.line_counts;modal(`<h2>真实边坡算法运行报告</h2><p>任务编号：${j.id}<br>输入来源：${j.source==='synthetic'?'合成台阶点云':'本机矿区点云'}<br>本次坡顶线：${counts.crest} 条 · 坡脚线：${counts.toe} 条<br>自动补线：${counts.auto_gap} 条 · 总长度：${j.result.total_length_m} m<br>运行耗时：${j.elapsed_s} 秒<br>坐标系：ENU 局部坐标</p><p>${j.source==='synthetic'?'此结果由真实算法对合成点云计算，不能作为矿区实测效果。':'此结果由真实算法对本地点云计算，精度需另行验收。'}</p><button id="downloadRealReport" class="primary">下载运行报告</button>`);$('#downloadRealReport').onclick=()=>{let html=$('#modalBody').cloneNode(true);html.querySelector('button').remove();download('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>真实边坡算法运行报告</title><style>body{font:16px sans-serif;max-width:900px;margin:40px auto;line-height:1.9}</style>'+html.innerHTML+'</html>','真实边坡算法运行报告-'+j.id+'.html','text/html;charset=utf-8')}}
const oldSceneView=sceneView;sceneView=function(id){if(id!=='slope')return oldSceneView(id);currentScene='slope';return heading('露天矿边坡线提取与自动补线','真实算法工作台 · 本机点云计算 · ENU 矢量成果输出','<button data-nav="scenarios">返回场景应用</button>')+`<div class="workspace real-workspace"><section class="panel"><div class="panel-head"><h2>场景与计算成果</h2><span class="badge">真实算法已接入</span></div><div class="viewer" id="viewer"><span class="view-label" id="viewLabel">原资料边坡线案例 · 运行后显示本次成果</span><img id="sceneImage" src="assets/slope.png" alt="边坡线提取成果"></div><div class="viewer-tools"><button data-image="original">资料案例图</button><button id="currentPreview">本次计算结果</button><button id="zoom">放大 / 复位</button><button id="fullscreen">全屏查看</button></div><p class="note" style="padding:15px">红线为坡顶线，蓝线为坡脚线。资料案例图与本次计算结果分别显示；合成点云只验证算法流程，实际矿区精度需另行验证。</p></section>${realPanel().replace('<div id="realResults"></div>','')}</div><div id="realResults"></div>`};
const oldReportView=reportView;reportView=function(){return realJob?.status==='succeeded'&&currentScene==='slope'?heading('真实算法成果与报告','统计来自本次点云计算，可下载 ENU 矢量、预览图和运行参数')+realResult(realJob):oldReportView()};
const originalRender=render;render=function(){originalRender();mountReal();if($('#currentPreview'))$('#currentPreview').onclick=()=>{if(realJob?.status==='succeeded'){$('#sceneImage').src=`/api/jobs/${realJob.id}/files/preview.png`;$('#viewLabel').textContent='本次真实计算结果'}else toast('请先完成一次真实算法运行')};if($('#realReport'))$('#realReport').onclick=()=>realReport(realJob);if(activeView==='tasks')loadRealTasks();};
async function loadRealTasks(){try{let d=await realFetch('/api/jobs');if(activeView!=='tasks'||!d.jobs.length)return;$('#realTasksPanel')?.remove();let el=document.createElement('section');el.id='realTasksPanel';el.className='panel result-panel';el.innerHTML='<h2>真实算法任务</h2><table><thead><tr><th>任务编号</th><th>输入来源</th><th>状态</th><th>耗时</th><th>操作</th></tr></thead><tbody>'+d.jobs.map(j=>`<tr><td>${j.id}</td><td>${j.source==='synthetic'?'合成点云验证':'本地点云'}</td><td>${({succeeded:'已完成',running:'运行中',queued:'等待运行',failed:'运行失败',cancelled:'已取消'})[j.status]}</td><td>${j.elapsed_s||'—'} 秒</td><td><button data-real-job="${j.id}">查看结果</button></td></tr>`).join('')+'</tbody></table>';app.append(el);el.querySelectorAll('[data-real-job]').forEach(b=>b.onclick=async()=>{let j=await realFetch('/api/jobs/'+b.dataset.realJob);selectedRealId=j.id;navigate('scene/slope');showRealJob(j);if(['queued','running'].includes(j.status))watchReal(j.id)})}catch{}}
window.removeEventListener('hashchange',originalRender);window.addEventListener('hashchange',render);render();
